import {createStore, unwrap} from 'solid-js/store';
import {StarGiftCollection} from '@layer';
import {batch, onMount} from 'solid-js';
import {MyStarGift} from '@appManagers/appGiftsManager';
import rootScope from '@lib/rootScope';
import type {AppManagers} from '@lib/managers';
import createListenerSetter from '@helpers/solid/createListenerSetter';
import {updateStarGift} from '@appManagers/utils/gifts/updateStarGift';
import {inputStarGiftEquals} from '@appManagers/utils/gifts/inputStarGiftEquals';
import untrackActions from '@helpers/solid/untrackActions';
import setBooleanFlag from '@helpers/object/setBooleanFlag';
import {getCanManagePeerGifts} from '@components/stargifts/canManageGifts';
import putInOrder from '@helpers/array/putInOrder';
import createOptimisticSave from '@helpers/createOptimisticSave';
import {bindManagersToSession} from '@lib/accounts/bindManagersToAccount';

export const ALL_COLLECTIONS_ID = -1

interface StarGiftsFilters {
  sort?: 'date' | 'value'
  chosenCollection?: number
  unlimited?: boolean
  limited?: boolean
  upgradable?: boolean
  unique?: boolean
  displayed?: boolean
  hidden?: boolean
}

export interface StarGiftsProfileStore extends Required<StarGiftsFilters> {
  items: MyStarGift[]
  collections: StarGiftCollection[] | undefined
  loading: boolean
  loaded: boolean
  canManageGifts: boolean
  hasCollections: boolean
  /** whether a message comes for each new gift: a channel's, for who can manage them, else `undefined` */
  chatNotificationsEnabled: boolean | undefined
}

export interface StarGiftsProfileActions {
  loadNext: (reload?: boolean) => Promise<void>
  setFilters: (filters: StarGiftsFilters) => void
  deleteCollection: (collectionId: number) => void
  /** `ids`: every collection's, in the order they are to be shown; at once and saved, as `toggleChatNotifications` */
  reorderCollections: (ids: number[]) => void
  /** at once, put back as the server last took it if refused with no newer change behind (`onSaveFailed`) */
  toggleChatNotifications: (enabled: boolean) => void
  handleSwipe: (xDiff: number, setCollectionOverride?: (collectionId: number) => void) => boolean
  updateCollection: (collection: StarGiftCollection, options?: {
    switch: boolean
    reload: boolean
  }) => void
}


export function createProfileGiftsStore(props: {
  peerId: PeerId
  initialFilters?: StarGiftsFilters
  onCountChange?: (count: number) => void
  /** a change shown at once was refused, and is put back */
  onSaveFailed?: () => void
  // a screen's own, bound to its account session; the tab's by default
  managers?: AppManagers
}): [StarGiftsProfileStore, StarGiftsProfileActions] {
  const initialState: StarGiftsProfileStore = {
    collections: undefined,
    items: [],
    loading: false,
    loaded: false,
    canManageGifts: props.peerId === rootScope.myId,
    chatNotificationsEnabled: undefined,

    chosenCollection: ALL_COLLECTIONS_ID,
    sort: 'date',
    unlimited: true,
    limited: true,
    upgradable: true,
    unique: true,
    displayed: true,
    hidden: true,
    ...props.initialFilters,
    get hasCollections() {
      return store.collections !== undefined && store.collections.length > 0;
    }
  }
  const [store, setStore] = createStore<StarGiftsProfileStore>(initialState);

  let currentOffset = '';
  let nextReqId = 0
  let fetchedCanManageGifts = false;
  // * a page the manager was asked for before a toggle may have been answered before it: the toggle has the last
  // * word (one asked for after waits there for the toggles on their way)
  let notificationsRevision = 0;

  // * the manager sends each setting's writes in turn, whichever store asked, and reads it after them; a refusal
  // * with no newer change behind it puts back what the server holds then
  const managers = props.managers ?? bindManagersToSession(rootScope.managers);
  const getCollectionId = (collection: StarGiftCollection) => collection.collection_id;
  const saveCollectionsOrder = createOptimisticSave((ids: number[]) => {
    return managers.appGiftsManager.reorderCollections(props.peerId, ids);
  }, (ids) => {
    // * not known either: left as dragged
    if(ids) {
      setStore('collections', putInOrder(unwrap(store.collections), ids, getCollectionId));
    }

    props.onSaveFailed?.();
  }, async() => {
    return (await managers.appGiftsManager.getCollections(props.peerId))?.map(getCollectionId);
  });
  const saveNotifications = createOptimisticSave((enabled: boolean) => {
    return managers.appGiftsManager.toggleChatGiftNotifications(props.peerId, enabled);
  }, (enabled) => {
    // * `undefined`, not known: the checkbox goes until a page says it
    setStore('chatNotificationsEnabled', enabled);
    props.onSaveFailed?.();
  }, () => managers.appGiftsManager.getChatGiftNotifications(props.peerId));

  const fetchCanManageGifts = () => getCanManagePeerGifts(props.peerId);

  const collectionCache = new Map<number, {items: MyStarGift[], offset: string, loaded: boolean}>();

  async function loadNext(reload = false) {
    if(!reload && (store.loading || store.loaded)) return
    setStore('loading', true);

    const id = ++nextReqId
    const notificationsRevisionAtStart = notificationsRevision
    const collectionId = store.chosenCollection === ALL_COLLECTIONS_ID ? undefined : store.chosenCollection
    const [res, canManageGifts] = await Promise.all([
      managers.appGiftsManager.getProfileGifts({
        peerId: props.peerId,
        offset: currentOffset,
        sort: store.sort,
        unlimited: store.unlimited,
        limited: store.limited,
        upgradable: store.upgradable,
        unique: store.unique,
        displayed: store.displayed,
        hidden: store.hidden,
        withCollections: store.collections === undefined,
        collectionId,
        limit: 99 // divisible by 3 to avoid grid jumping
      }),
      fetchedCanManageGifts ? Promise.resolve(store.canManageGifts) : fetchCanManageGifts()
    ]);

    if(id !== nextReqId) return;
    currentOffset = res.next;
    batch(() => {
      if(!fetchedCanManageGifts) {
        fetchedCanManageGifts = true;
        setStore('canManageGifts', canManageGifts);
      }

      setStore('items', reload ? res.gifts : store.items.concat(res.gifts))
      setStore('loaded', !res.next)
      setStore('loading', false)
      if(res.collections) {
        setStore('collections', res.collections)
      }
      if(res.chatNotificationsEnabled !== undefined && notificationsRevisionAtStart === notificationsRevision) {
        setStore('chatNotificationsEnabled', res.chatNotificationsEnabled)
      }
    })
    if(
      collectionId === undefined &&
      store.unlimited &&
      store.limited &&
      store.upgradable &&
      store.unique &&
      store.displayed &&
      store.hidden
    ) {
      props.onCountChange?.(res.count);
    }
  }

  function reload(background = false) {
    currentOffset = ''
    fetchedCanManageGifts = false
    batch(() => {
      setStore('loading', true)
      setStore('loaded', false)
      if(!background) {
        setStore('items', [])
      }
    })
    loadNext(true)
  }

  const actions: StarGiftsProfileActions = {
    loadNext,
    setFilters: (filters) => {
      const onlyCollectionChange = Object.keys(filters).length === 1 && filters.chosenCollection !== undefined
      const switchingCollection = onlyCollectionChange && filters.chosenCollection !== store.chosenCollection

      if(!onlyCollectionChange) {
        collectionCache.clear()
      }

      if(switchingCollection) {
        // save current collection state
        collectionCache.set(store.chosenCollection, {
          items: unwrap(store.items),
          offset: currentOffset,
          loaded: store.loaded
        })
      }

      setStore(filters)

      if(switchingCollection) {
        const cached = collectionCache.get(store.chosenCollection)
        if(cached) {
          currentOffset = cached.offset
          batch(() => {
            setStore('items', cached.items)
            setStore('loaded', cached.loaded)
            setStore('loading', false)
          })
          return
        }
      }

      reload()
    },
    deleteCollection: (collectionId) => {
      collectionCache.delete(collectionId)
      const deletingChosenCollection = store.chosenCollection === collectionId

      batch(() => {
        if(deletingChosenCollection) {
          setStore('chosenCollection', ALL_COLLECTIONS_ID)
        }
        setStore('collections', store.collections.filter((it) => it.collection_id !== collectionId))
      })

      if(deletingChosenCollection) {
        reload()
      }
    },
    reorderCollections: (ids) => {
      const collections = unwrap(store.collections);
      setStore('collections', putInOrder(collections, ids, getCollectionId))
      saveCollectionsOrder(ids, collections.map(getCollectionId))
    },
    toggleChatNotifications: (enabled) => {
      const shown = store.chatNotificationsEnabled;
      setStore('chatNotificationsEnabled', enabled)
      ++notificationsRevision;
      saveNotifications(enabled, shown)
    },
    updateCollection: (collection, options) => {
      collectionCache.delete(collection.collection_id)
      const needSwitch= options?.switch ?? true
      let needReload = options?.reload ?? needSwitch

      batch(() => {
        const newArray = store.collections.slice();
        const idx = newArray.findIndex((it) => it.collection_id === collection.collection_id);
        if(idx !== -1) {
          newArray[idx] = collection;
        } else {
          newArray.push(collection);
        }
        setStore('collections', newArray);
        if(needSwitch) {
          setStore('chosenCollection', collection.collection_id)
          needReload = true
        }
      })
      if(needReload) {
        reload()
      }
    },
    handleSwipe: (xDiff: number, setCollectionOverride?: (collectionId: number) => void) => {
      if(!store.hasCollections) return false
      const direction = xDiff > 0 ? 1 : -1

      const collections$ = store.collections;
      const chosenCollection$ = store.chosenCollection;
      const currentIndex =
        chosenCollection$ === ALL_COLLECTIONS_ID ? -1 :
        collections$.findIndex((it) => it.collection_id === chosenCollection$);
      const newIndex = currentIndex + direction;
      if(newIndex < -1 || newIndex >= collections$.length) return false

      const newCollectionId = newIndex === -1 ? ALL_COLLECTIONS_ID : collections$[newIndex].collection_id
      if(setCollectionOverride) {
        setCollectionOverride(newCollectionId)
      } else {
        actions.setFilters({chosenCollection: newCollectionId})
      }

      return true
    }
  }
  untrackActions(actions as any);

  const listenerSetter = createListenerSetter()
  onMount(() => {
    listenerSetter.add(rootScope)('star_gift_update', (event) => {
      collectionCache.clear()
      const items = unwrap(store.items);
      const idx = items.findIndex((it) => inputStarGiftEquals(it, event.input));
      if(idx !== -1) {
        const newList = items.slice();
        // create a new object to force re-render
        const newItem = {...newList[idx]};
        newList[idx] = newItem;

        updateStarGift(newItem, event);

        setStore('items', newList);
      }
    });

    listenerSetter.add(rootScope)('pinned_stargifts', (event) => {
      if(event.peerId !== props.peerId) return;
      collectionCache.clear()

      const items = unwrap(store.items).slice();
      for(let i = 0; i < items.length; i++) {
        const item = items[i];
        const shouldBePinned = event.gifts.some((it) => inputStarGiftEquals(item, it))
        const wasPinned = !!item.saved.pFlags.pinned_to_top

        if(shouldBePinned !== wasPinned) {
          items[i] = {...item} // force re-render
          setBooleanFlag(items[i].saved.pFlags, 'pinned_to_top', shouldBePinned)
        }
      }

      items.sort((a, b) => {
        if(a.saved.pFlags.pinned_to_top && !b.saved.pFlags.pinned_to_top) return -1;
        if(!a.saved.pFlags.pinned_to_top && b.saved.pFlags.pinned_to_top) return 1;
        if(a.saved.pFlags.pinned_to_top && b.saved.pFlags.pinned_to_top) {
          const idxA = event.gifts.findIndex((it) => inputStarGiftEquals(a, it))
          const idxB = event.gifts.findIndex((it) => inputStarGiftEquals(b, it))
          return idxA - idxB
        };
        return b.saved.date - a.saved.date;
      })
      setStore('items', items);
    })

    listenerSetter.add(rootScope)('star_gift_list_update', ({peerId}) => {
      if(peerId !== props.peerId) return
      collectionCache.clear()

      // refetch list. wait a bit so that the server can process it.
      setTimeout(() => {
        currentOffset = ''
        loadNext(true)
      }, 500)
    })
  })

  return [store, actions]
}
